from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tree):
    # LeetCode list -> linked nodes. Each popped parent takes the next two slots.
    if not tree or tree[0] is None:
        return None
    root = Node(tree[0])
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        node = queue.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = Node(tree[i])
            queue.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = Node(tree[i])
            queue.append(node.right)
        i += 1
    return root

def height(node):
    # Height in nodes, by BFS over the subtree (no recursion).
    if node is None:
        return 0
    levels = 0
    queue = deque([node])
    while queue:
        levels += 1
        for _ in range(len(queue)):
            cur = queue.popleft()
            if cur.left is not None:
                queue.append(cur.left)
            if cur.right is not None:
                queue.append(cur.right)
    return levels

def solution(tree):
    # Measure both subtrees of every node from scratch: O(n^2) on a chain.
    root = build(tree)
    if root is None:
        return [0, 0]
    best = 0
    stack = [root]
    while stack:
        node = stack.pop()
        best = max(best, height(node.left) + height(node.right))
        for child in (node.left, node.right):
            if child is not None:
                stack.append(child)
    return [height(root), best]
